      'hi':
          'व्यय आमतौर पर \"भत्ता\" (पूर्व में दी जाने वाली एक निश्चित राशि) से भिन्न होता है।\n\nव्यय की प्रतिपूर्ति आमतौर पर की जाती है, जिसका अर्थ है कि आप\nपहले अपना पैसा खर्च करते हैं और बाद में आपको वह राशि वापस मिल जाती है।',
