      'ta':
          'ஒரு செலவு பொதுவாக \n\"கொடுப்பனவு\" (முன்கூட்டியே கொடுக்கப்பட்ட ஒரு நிர்ணயிக்கப்பட்ட தொகை) இலிருந்து வேறுபட்டது. \n\nசெலவுகள் பொதுவாக திருப்பிச் செலுத்தப்படுகின்றன, அதாவது நீங்கள் \nஉங்கள் சொந்தப் பணத்தை முதலில் செலவழித்து பின்னர் பணம் பெறுவீர்கள்.',
