    '5c0ghwdq': {
      'en':
          'Enabling location access allows us to provide you with faster and more accurate information based on your current location. We also need background location permission to ensure continuous service even when you\'re not using the app',
      'hi':
          'लोकेशन एक्सेस चालू करने से हमें आपकी वर्तमान लोकेशन के आधार पर आपको तेज़ और सटीक जानकारी प्रदान करने में मदद मिलती है। ऐप का उपयोग न करने पर भी निरंतर सेवा सुनिश्चित करने के लिए हमें बैकग्राउंड लोकेशन अनुमति की आवश्यकता होती है।',
      'mr':
          'स्थान प्रवेश सक्षम केल्याने आम्हाला तुमच्या सध्याच्या स्थानावर आधारित जलद आणि अधिक अचूक माहिती प्रदान करण्याची परवानगी मिळते. तुम्ही अ‍ॅप वापरत नसतानाही सतत सेवा सुनिश्चित करण्यासाठी आम्हाला पार्श्वभूमी स्थान परवानगी देखील आवश्यक आहे.',
